module top_module(
    input [9:0] baud_divisor,
    input clk,
    input clk_en,
    input reset_n,
    input rx_char_ready,
    input rxd,
    output reg source_rxd
);reg [7:0] stim_data = 8'b0;
reg [7:0] d1_stim_data = 8'b0;
reg delayed_rx_char_ready;
wire pickup_pulse;
wire do_send_stim_data;

always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
        delayed_rx_char_ready <= 1'b0;
        d1_stim_data <= 8'b0;
    end else if (clk_en) begin
        delayed_rx_char_ready <= rx_char_ready;
        d1_stim_data <= do_send_stim_data ? stim_data : d1_stim_data;
    end
end

assign pickup_pulse = ~rx_char_ready & delayed_rx_char_ready;
assign do_send_stim_data = pickup_pulse || 1'b0;

always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
        source_rxd <= 1'b0;
    end else if (do_send_stim_data) begin
        source_rxd <= d1_stim_data[0];
    end
end

endmodule

