module top_module(
    input clkhx,
    input clk1x,
    input i_reset,
    output r_reset
);// Define the clock enable signal for the D flip-flop
    `ifdef CNY_ALTERA
    (* noprune = 1 *)
    (* syn_preserve = 1 *)
    reg r_rsthx;
    always @(posedge clkhx) begin
        if (i_reset)
            r_rsthx <= 1'b1;
        else
            r_rsthx <= 1'b0;
    end
    `else //!CNY_ALTERA
    reg r_rsthx;
    always @(posedge clkhx or posedge i_reset) begin
        if (i_reset)
            r_rsthx <= 1'b1; // Set on reset
        else
            r_rsthx <= !r_rsthx; // Toggle
    end
    `endif //!CNY_ALTERA

    // Define the reset signal for the D flip-flop
    reg r_rst;
    always @(posedge clk1x) begin
        r_rst <= r_rsthx;
    end

    // Define the output of the module
    assign r_reset = r_rst;

endmodule

