module top_module(
  input clk,
  input NS_VEHICLE_DETECT,
  input EW_VEHICLE_DETECT,
  output reg NS_RED,
  output reg NS_YELLOW,
  output reg NS_GREEN,
  output reg EW_RED,
  output reg EW_YELLOW,
  output reg EW_GREEN
);// Counters
  reg[4:0] count1;
  reg[3:0] count2;
  reg[1:0] count3;

  // Counter Modules
  always @(posedge clk) begin
    if (count1 == 31) begin
      count1 <= 0;
    end
    else begin
      count1 <= count1 + 1;
    end
  end

  always @(posedge clk) begin
    if (count2 == 15) begin
      count2 <= 0;
    end
    else begin
      count2 <= count2 + 1;
    end
  end

  always @(posedge clk) begin
    if (count3 == 3) begin
      count3 <= 0;
    end
    else begin
      count3 <= count3 + 1;
    end
  end

  // Main Traffic Module
  always @(posedge clk) begin
    if (count3 == 3) begin
      // Yellow light
      NS_YELLOW <= 1;
      EW_YELLOW <= 1;
      NS_GREEN <= 0;
      EW_GREEN <= 0;
      NS_RED <= 0;
      EW_RED <= 0;
    end
    else if (count2 == 15) begin
      // EW green light
      NS_YELLOW <= 0;
      EW_YELLOW <= 0;
      NS_GREEN <= 0;
      EW_GREEN <= 1;
      NS_RED <= 1;
      EW_RED <= 0;
      if (EW_VEHICLE_DETECT == 1) begin
        count2 <= count2 - 6;
      end
    end
    else if (count1 == 31) begin
      // NS green light
      NS_YELLOW <= 0;
      EW_YELLOW <= 0;
      NS_GREEN <= 1;
      EW_GREEN <= 0;
      NS_RED <= 0;
      EW_RED <= 1;
      if (NS_VEHICLE_DETECT == 1) begin
        count1 <= count1 - 8;
      end
    end
    else begin
      // Red light
      NS_YELLOW <= 0;
      EW_YELLOW <= 0;
      NS_GREEN <= 0;
      EW_GREEN <= 0;
      NS_RED <= 1;
      EW_RED <= 1;
    end
  end

endmodule

