    input load,
    input [3:0] in,
    output reg [3:0] out,
    output reg [3:0] out_next
);reg [3:0] stage1, stage2, stage3, stage4;

    always @(posedge clk) begin
        if (load) begin
            stage1 <= in;
            stage2 <= stage1;
            stage3 <= stage2;
            stage4 <= stage3;
        end else begin
            stage1 <= stage2;
            stage2 <= stage3;
            stage3 <= stage4;
            stage4 <= out_next;
        end
    end

    assign out = stage1;
    assign out_next = stage2;

endmodule

