module counter_4bit(
    input clk,          // Clock signal.
    input rst,          // Asynchronous reset signal.
    input en,           // Enable signal to activate the counter.

    output [3:0] out    // 4-bit binary counter output.
);

reg [3:0] count;

//------------------------------------------------
// Counter logic
always @(posedge clk or posedge rst) begin
    if (rst) begin
        count <= 4'b0000;
    end else if (en) begin
        count <= count + 1;
    end
end

assign out = count;

endmodule

