module top_module(
    input clk,
    input rst,
    input ena,
    output reg [3:0] q
);reg [3:0] q_next;

always @(posedge clk) begin
    if (rst) begin
        q <= 4'b0000;
    end
    else if (ena) begin
        q <= q_next;
    end
end

always @(*) begin
    q_next[0] = q[3] ^ ~q[1];
    q_next[1] = q[0] ^ ~q[2];
    q_next[2] = q[1] ^ ~q[3];
    q_next[3] = q[2] ^ ~q[0];
end

endmodule

module top_module (
    input clk,
    input areset,
    output [4:0] count );reg [4:0] count_reg;

    always @(posedge clk or posedge areset) begin
        if (areset)
            count_reg <= 5'b00000;
        else
            count_reg <= count_reg + 1;
    end

    assign count = count_reg;

endmodule

module adder_subtractor(
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] result,
    output carry_out
    );

    wire [31:0] b_comp;
    wire [31:0] sum;
    wire carry;

    // Complement 'b' if subtraction is to be performed
    assign b_comp = sub ? ~b + 1 : b;
    assign {carry, sum} = a + b_comp;

    assign result = sum;
    assign carry_out = carry;

endmodule

module shift_reg(clk, rst, d, q);

    input  clk;
    input  rst;
    input  d;
    output reg [3:0] q;

    always @(posedge clk or posedge rst) begin
        if (rst)
            q <= 4'b0000;
        else
            q <= {q[2:0], d};
    end

endmodule

module fsm_moore_1011(IN, MATCH, CLK, RST);
input IN, CLK, RST;
output reg MATCH;

reg [2:0] state, next_state;

parameter S0 = 3'b000;
parameter S1 = 3'b001;
parameter S2 = 3'b010;
parameter S3 = 3'b011;
parameter S4 = 3'b100;

always @(posedge CLK or posedge RST) begin
    if (RST)
        state <= S0;
    else
        state <= next_state;
end

always @(*) begin
    case (state)
        S0: begin
            if (IN == 1)
                next_state = S1;
            else
                next_state = S0;
        end
        S1: begin
            if (IN == 0)
                next_state = S2;
            else
                next_state = S1;
        end
        S2: begin
            if (IN == 1)
                next_state = S3;
            else
                next_state = S0;
        end
        S3: begin
            if (IN == 1)
                next_state = S4;
            else
                next_state = S1;
        end
        S4: begin
            if (IN == 1)
                next_state = S1;
            else
                next_state = S0;
        end
        default: next_state = S0;
    endcase
end

always @(posedge CLK or posedge RST) begin
    if (RST)
        MATCH <= 0;
    else if (state == S4)
        MATCH <= 1;
    else
        MATCH <= 0;
end

endmodule

