module top_module(
  input clk,
  input reset,
  input data,
  output reg match
);parameter IDLE = 2'b00, S0 = 2'b01, S1 = 2'b10, S2 = 2'b11;
reg [1:0] state, next_state;

always @ (posedge clk) begin
  if (reset) begin
    state <= IDLE;
    match <= 0;
  end else begin
    state <= next_state;
    if (state == S2) begin
      match <= 1;
    end else begin
      match <= 0;
    end
  end
end

always @(*) begin
  case (state)
    IDLE: begin
      if (data == 1'b1) begin
        next_state = S0;
      end else begin
        next_state = IDLE;
      end
    end
    S0: begin
      if (data == 1'b0) begin
        next_state = IDLE;
      end else begin
        next_state = S1;
      end
    end
    S1: begin
      if (data == 1'b1) begin
        next_state = S2;
      end else begin
        next_state = IDLE;
      end
    end
    S2: begin
      next_state = IDLE;
    end
  endcase
end

endmodule

