module top_module(
   input clk,
   input [31:0] n,
   input start,
   output reg [31:0] fibn,
   output reg done
);reg [31:0] in_n;

   reg [2:0] state;
   reg [2:0] nextstate;

   reg [31:0] b;
   reg [31:0] h;
   reg [31:0] d;
   reg [31:0] f;

   wire [31:0] nextn;
   wire [31:0] nextb;
   wire [31:0] nexth;
   wire [31:0] nextd;
   wire [31:0] nextf;

   assign nextn = in_n / 2;
   assign nextb = (b * f) + (d * f) + (b * h);
   assign nexth = (f * f) + (h * h);
   assign nextd = (b * f) + (d * h);
   assign nextf = (f * f) + (2 * f * h);

   always @(posedge clk) begin
      state <= nextstate;
   end

   always @(posedge clk) begin
      case (state)
         0: begin
            done <= 1;
            fibn <= 0;
            in_n <= n;
            if (start) begin
               nextstate <= 1;
            end
         end
         1: begin
            done <= 0;
            b <= 0;
            h <= 0;
            d <= 1;
            f <= 1;
            nextstate <= 2;
         end
         2: begin
            if (in_n <= 0) begin
               nextstate <= 0;
               fibn <= b;
               done <= 1;
            end else begin
               nextstate <= 3;
            end
         end
         3: begin
            if (in_n & 1 == 1) begin
               b <= nextb;
               d <= nextd;
            end

            f <= nextf;
            h <= nexth;
            in_n <= nextn;

            nextstate <= 2;
         end
      endcase
   end

endmodule

