description:
Design a circuit that implements a majority gate for four input bits (A, B, C, D). The output (X) will be HIGH if at least three of the inputs are HIGH, effectively detecting whether the majority of the inputs are in the active state. The functionality is realized by utilizing combinations of AND and OR gates to evaluate the presence of a majority in the input signals.
module top_module(
    // input ports
    input A,
    input B,
    input C,
    input D,
    // output ports
    output X
);

code:
module top_module(
    // input ports
    input A,
    input B,
    input C,
    input D,
    // output ports
    output X
);wire AB = A & B;
    wire AC = A & C;
    wire AD = A & D;
    wire BC = B & C;
    wire BD = B & D;
    wire CD = C & D;

    wire majority1 = AB | AC | AD | BC | BD | CD;
    wire majority0 = ~AB & ~AC & ~AD & ~BC & ~BD & ~CD;

    assign X = (majority1 & ~majority0);

endmodule

