    input reset,    // Synchronous active-high reset
    input [7:0] d,  // Input to the T flip-flop
    input [7:0] in, // 8-bit input for the module to detect changes
    output [7:0] out // Final 8-bit output from the bitwise AND operation of the two modules
);// Instantiate the T flip-flop
reg t;
always @(posedge clk, posedge reset) begin
    if (reset) begin
        t <= 1'b0;
    end else begin
        t <= d ^ t;
    end
end

// Instantiate the module to detect changes in the 8-bit vector
reg [7:0] prev_in;
reg [7:0] changed_bits;
always @(posedge clk, posedge reset) begin
    if (reset) begin
        prev_in <= 8'b0;
        changed_bits <= 8'b0;
    end else begin
        changed_bits <= in ^ prev_in;
        prev_in <= in;
    end
end

// Instantiate the functional module that performs the bitwise AND operation
assign out = t & changed_bits;

endmodule

