module top_module(
    input rst,
    input wr_clk,
    input rd_clk,
    input [102:0] din,
    input wr_en,
    input rd_en,
    output reg [102:0] dout, // Change to reg type
    output full,
    output empty,
    output prog_full
);// Internal FIFO memory
    reg [102:0] mem [0:102];
    // Write and read pointers
    reg [6:0] wr_ptr = 7'b0;
    reg [6:0] rd_ptr = 7'b0;
    // Full and empty flags
    wire is_full = (wr_ptr == (103 - 1)) & (wr_en == 1);
    wire is_empty = (rd_ptr == wr_ptr) & (rd_en == 1);
    wire is_prog_full = (wr_ptr == (103 - 4)) & (wr_en == 1);

    // Write logic
    always @(posedge wr_clk) begin
        if (rst) begin
            wr_ptr <= 7'b0;
        end else if (wr_en && !is_full) begin // Check for full condition
            mem[wr_ptr] <= din;
            wr_ptr <= (wr_ptr == (103 - 1)) ? 7'b0 : wr_ptr + 1'b1;
        end
    end

    // Read logic
    always @(posedge rd_clk) begin
        if (rst) begin
            rd_ptr <= 7'b0;
        end else if (rd_en && !is_empty) begin // Check for empty condition
            dout <= mem[rd_ptr];
            mem[rd_ptr] <= 0; // Optional: clear the memory at this location
            rd_ptr <= (rd_ptr == (103 - 1)) ? 7'b0 : rd_ptr + 1'b1;
        end
    end

    // Output signals
    assign full = is_full;
    assign empty = is_empty;
    assign prog_full = is_prog_full;

endmodule

