 wire [27:0] R; 
 wire [55:0] Dtmp; 
 assign L = Din[55:28]; 
 assign R = Din[27:0]; 
 assign Dtmp = {(L << shift_count) | (L >> (28-shift_count)), (R << shift_count) | (R >> (28-shift_count))}; 
 assign Dout = Dtmp; 
 endmodule

