module top_module(DOUTB,
    ENA,
    clka,
    ENB,
    clkb,
    addra,
    addrb,
    dina);output reg [0:0] DOUTB; // Changed to reg type since we'll be assigning value in an always block
  input ENA;
  input clka;
  input ENB;
  input clkb;
  input [15:0] addra;
  input [15:0] addrb;
  input [0:0] dina;

  // Memory storage (128x1 bits as an example)
  reg [0:0] memory [0:127];

  always @(posedge clka) begin
    if (ENA) begin
      memory[addra] <= dina; // Write operation
    end
  end

  always @(posedge clkb) begin
    if (ENB) begin
      DOUTB <= memory[addrb]; // Read operation
    end
  end
endmodule

